<script setup lang="ts">
import {pageHeaders} from '../client/index';
import ApiKeysPanel from './ApiKeysPanel.vue';
import {ref,toRefs} from 'vue';import {commandCredentials} from '../state/access';import {ui,request,loadConnections} from '../state/device';import {t} from '../state/appearance';import Icon from '../components/Icon.vue';import InfoButton from '../components/InfoButton.vue';
const {user,password}=toRefs(commandCredentials);const busy=ref(false);
const results=ref<{name:string|(()=>string);status:number;expected:number;challenge:string;body:string;valid?:boolean}[]>([]);
const credentials=(secret:string)=>'Basic '+btoa(user.value+':'+secret);
async function verify(){busy.value=true;results.value=[];try{
 const cases=[{path:'/api/v2/auth/status',name:()=>t('Без заголовка','No header'),expected:401,header:''},{path:'/api/v2/auth/status',name:()=>t('Неверный пароль','Wrong password'),expected:401,header:credentials(password.value+'-wrong')},{path:'/api/v2/auth/status',name:()=>t('Правильные данные','Valid credentials'),expected:200,header:credentials(password.value)},{path:'/api/v2/auth/admin',name:()=>t('Недостаточно прав','Insufficient permissions'),expected:403,header:credentials(password.value)},{path:'/api/v2/events/private',name:()=>t('SSE без доступа','SSE without credentials'),expected:401,header:''}];
 for(const item of cases){const r=await request(item.path,{headers:item.header?{Authorization:item.header}:{}});results.value.push({name:item.name,status:r.status,expected:item.expected,challenge:r.challenge??'—',body:r.text});}
 }catch(error){results.value.push({name:String(error),status:0,expected:200,challenge:'—',body:''});}finally{busy.value=false;}}
async function protectedStream(){busy.value=true;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),5000);let reader:ReadableStreamDefaultReader<Uint8Array>|undefined;try{
 const r=await fetch('/api/v2/events/private',{headers:pageHeaders({Authorization:credentials(password.value)}),credentials:'omit',signal:controller.signal});let event='';
 if(r.ok&&r.headers.get('content-type')?.startsWith('text/event-stream')){reader=r.body?.getReader();const decoder=new TextDecoder();while(reader&&!event.includes('\n\n')&&event.length<4096){const part=await reader.read();if(part.done)break;event+=decoder.decode(part.value,{stream:true});}}
 results.value.push({name:()=>t('SSE с авторизацией','Authenticated SSE'),status:r.status,expected:200,challenge:r.headers.get('www-authenticate')??'—',valid:event.includes('event: diagnostic'),body:event.includes('event: diagnostic')?event:t('Нет диагностического события','No diagnostic event')});
 }catch(error){results.value.push({name:()=>t('SSE с авторизацией','Authenticated SSE'),status:0,expected:200,challenge:'—',body:String(error)});}finally{controller.abort();await reader?.cancel().catch(()=>{});clearTimeout(timeout);busy.value=false;}}
</script>
<template><section class="panel"><div class="panel-head"><h2><Icon name="lock"/>{{t('Учётные данные и проверки доступа','Credentials and access probes')}}</h2><InfoButton :label="t('Доступ','Access')" :text="t('Эта пара используется проверками и управлением на странице «Эксперименты», хранится только до перезагрузки страницы. Тестовая учётная запись demo / showcase-only имеет маску прав 1. Маршрут admin требует маску 2 и возвращает 403. Без корректных данных возвращается 401 с WWW-Authenticate. HTTP Basic не шифрует данные; это публичная тестовая пара. Проверки не меняют устройство.','These credentials are shared by probes and the Experiments controls, and live only until page reload. Fixture demo / showcase-only has permission mask 1. The admin route requires mask 2 and returns 403. Missing or invalid credentials return 401 with WWW-Authenticate. HTTP Basic does not encrypt credentials; this is a public test fixture. Probes do not change the device.')"/></div><div class="notice">{{t('Открытая тестовая пара','Public test fixture')}}: <code>demo / showcase-only</code> · Basic / HTTP</div><form class="auth-form" @submit.prevent="verify"><label>{{t('Пользователь','User')}}<input v-model="user" autocomplete="off" maxlength="64"></label><label>{{t('Пароль','Password')}}<input v-model="password" type="password" autocomplete="off" maxlength="64"></label><button class="primary" :disabled="busy" data-testid="auth-verify"><Icon name="shield-question"/>{{t('Проверить доступ','Verify access')}}</button><button type="button" :disabled="busy" data-testid="auth-sse" @click="protectedStream">{{t('Открыть защищённый SSE','Open protected SSE')}}</button></form><div class="table-wrap"><table data-testid="auth-matrix"><thead><tr><th>{{t('Проверка','Probe')}}</th><th>HTTP</th><th>{{t('Ожидание','Expected')}}</th><th>WWW-Authenticate</th><th>{{t('Результат','Result')}}</th></tr></thead><tbody><tr v-for="(r,i) in results" :key="i"><td>{{typeof r.name==='function'?r.name():r.name}}</td><td>{{r.status}}</td><td>{{r.expected}}</td><td><code>{{r.challenge}}</code></td><td :class="r.valid!==false&&r.status===r.expected&&(r.expected!==401||r.challenge.startsWith('Basic'))?'ok':'bad'">{{r.valid!==false&&r.status===r.expected&&(r.expected!==401||r.challenge.startsWith('Basic'))?'PASS':'FAIL'}}</td></tr></tbody></table></div><pre v-if="results.length" class="terminal">{{results.at(-1)?.body}}</pre><div v-if="ui.info?.capabilities.connections?.supported"><button @click="loadConnections(user,password)">{{t('Показать WS-соединения','Inspect WS connections')}}</button><div v-for="c in ui.connections" :key="c.id" class="connection-item mono">{{c.id}} · {{c.state}} · RX {{c.rx_frames}} / TX {{c.tx_frames}}</div></div></section><ApiKeysPanel/><section class="panel"><div class="panel-head"><h2>WS / {{t('границы защиты','security boundary')}}</h2></div><p class="notice"><Icon name="alert-triangle"/>{{t('WebSocket публичный. Прикладная политика этого демо оставляет WS публичным; ранние middleware ядра позволяют ограничить handshake.','WebSocket is public. This demo leaves WS public by application policy; core early middleware can protect the handshake.')}}</p></section></template>
